sp_widget.client_script:
api.controller = function() {
    // Check if approval data exists
    if (data.approvalList && data.approvalList.length > 0) {
        $scope.approvalList = data.approvalList;
    } else {
        $scope.noApprovalsMessage = "No pending approvals at the moment.";
    }

    // Function to approve or reject an approval record
    $scope.handleApproval = function(approvalId, action) {
        // GlideRecord to get the approval record by ID
        var gr = new GlideRecord('sysapproval_approver');
        if (gr.get(approvalId)) {
            gr.state = action === 'approve' ? 'approved' : 'rejected';
            gr.update();

            // Remove the processed approval from the list
            $scope.approvalList = $scope.approvalList.filter(function(item) {
                return item.approval_id !== approvalId;
            });
            $scope.$apply();
        }
    };
}();

sp_widget.css:
.approval-list-widget {
    font-family: Arial, sans-serif;
}

.approval-item {
    border: 1px solid #ddd;
    margin: 10px 0;
    padding: 15px;
    background-color: #f9f9f9;
}

.approval-actions button {
    margin-right: 10px;
}

sp_widget.script:
(function() {
    // Initialize the approval list
    var approvalList = [];

    // GlideRecord query to retrieve approval records for the current HR Manager
    var approvalGr = new GlideRecord('sysapproval_approver');

    // Filter approvals that are 'Requested' and assigned to the logged-in HR Manager
    approvalGr.addQuery('state', 'requested'); 
    approvalGr.addQuery('approver', gs.getUserID()); // Only approvals for the current HR Manager
    approvalGr.query();

    // Collect data into approvalList
    while (approvalGr.next()) {
        approvalList.push({
            approval_id: approvalGr.sys_id.toString(),
            request_number: approvalGr.request.number,
            request_type: approvalGr.request.sys_class_name,
            approval_state: approvalGr.state.getDisplayValue(),
            requested_for: approvalGr.requested_for.getDisplayValue(),
            date_requested: approvalGr.sys_created_on.getDisplayValue()
        });
    }

    // Pass the list to the client-side script
    data.approvalList = approvalList;
})();
